<?php
declare(strict_types=1);
$preview=isset($_GET['preview']);
if($preview){require_once __DIR__.'/../auth_check.php';if(!hasPermission('acces_admin')){http_response_code(403);exit('Accès refusé');}}
require_once __DIR__.'/../model/Database.php';
require_once __DIR__.'/../model/CompanyBranding.php';
require_once __DIR__.'/SiteContent.php';
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
$db=Database::getConnection();$brand=CompanyBranding::get($db);
try{$row=SiteContent::read($db);}catch(PDOException $e){$row=[];}
$json=$row[$preview?'draft_json':'published_json']??null;$available=$preview||!empty($json);
$data=SiteContent::decode($json,$brand);$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$logo=CompanyBranding::logoUrl('../',$db);$icon=CompanyBranding::iconUrl('../',$db);
$media=static fn($id)=>'media.php?id='.rawurlencode($id).($preview?'&preview=1':'');
$sections=['about'=>'À propos','services'=>'Nos activités','projects'=>'Nos réalisations','values'=>'Nos engagements','news'=>'Actualités'];
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($available?($data['seo_title']?:$brand['company_name']):'Site en préparation')?></title><?php if($preview||!$available):?><meta name="robots" content="noindex,nofollow"><?php else:?><meta name="description" content="<?=$h($data['seo_description'])?>"><?php endif;?><?php if($icon):?><link rel="icon" href="<?=$h($icon)?>"><?php endif;?><link rel="stylesheet" href="../branding_theme.php"><link rel="stylesheet" href="site.css"></head><body class="public-site"><?php if($preview):?><div class="preview-banner">Aperçu privé du brouillon · <a href="index.php">Retour au studio</a></div><?php endif;?>
<header class="public-nav"><div class="public-inner nav-inner"><a class="public-brand" href="#accueil"><?php if($logo):?><img src="<?=$h($logo)?>" alt=""><?php endif;?><strong><?=$h($brand['company_name'])?></strong></a><?php if($available):?><nav aria-label="Navigation"><?php foreach($sections as $key=>$label):if(empty($data[$key]))continue;?><a href="#<?=$key?>"><?=$h($label)?></a><?php endforeach;?><?php if($data['show_contact']):?><a href="#contact">Contact</a><?php endif;?></nav><?php endif;?></div></header>
<main id="accueil"><section class="hero premium-hero"><?php if($available&&$data['hero_image']):?><img class="hero-photo" src="<?=$h($media($data['hero_image']))?>" alt=""><?php endif;?><div class="public-inner hero-content"><span class="kicker"><?=$h($available&&$data['tagline']?$data['tagline']:$brand['company_name'])?></span><h1><?=$h($available?$data['headline']:'Notre site est en préparation')?></h1><p><?=$h($available?$data['intro']:'Nous vous invitons à revenir prochainement.')?></p><div class="hero-actions"><?php if($available&&$data['show_contact']):?><a class="button accent" href="#contact">Parlons de votre projet <span aria-hidden="true">↗</span></a><?php endif;?><?php if($available&&$data['services']):?><a class="button hero-secondary" href="#services">Découvrir nos activités</a><?php endif;?></div></div><div class="hero-decoration" aria-hidden="true"></div></section>
<?php if($available):?>
<?php if($data['figures']):?><section class="figure-band"><div class="public-inner figure-grid"><?php foreach($data['figures'] as $item):?><div><strong><?=$h($item['title'])?></strong><span><?=$h($item['body'])?></span></div><?php endforeach;?></div></section><?php endif;?>
<?php foreach($sections as $key=>$label):if(empty($data[$key]))continue;?><section class="public-section section-<?=$key?>" id="<?=$key?>"><div class="public-inner"><div class="section-heading"><span class="section-kicker"><?=$h($brand['company_name'])?> / <?=$h($label)?></span><h2><?=$h($label)?></h2></div><?php if($key==='about'):?><div class="about-grid"><div><p class="prose"><?=nl2br($h($data[$key]))?></p></div><?php if($data['about_image']):?><img class="about-photo" src="<?=$h($media($data['about_image']))?>" alt="Présentation de l’entreprise" loading="lazy"><?php endif;?></div><?php else:?><div class="public-grid"><?php foreach($data[$key] as $i=>$item):?><article><span class="card-index"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><h3><?=$h($item['title'])?></h3><p><?=$h($item['body'])?></p></article><?php endforeach;?></div><?php endif;?></div></section><?php endforeach;?>
<?php if($data['show_contact']):?><section id="contact" class="contact"><div class="public-inner contact-grid"><div><span class="kicker">Entrons en relation</span><h2>Parlons de votre projet.</h2><p>Retrouvez les coordonnées de notre entreprise.</p></div><div><?php foreach(['address'=>'Adresse','phone'=>'Téléphone','email'=>'Email'] as $key=>$label):if(empty($brand[$key]))continue;?><p><strong><?=$label?></strong><br><?php if($key==='email'&&filter_var($brand[$key],FILTER_VALIDATE_EMAIL)):?><a href="mailto:<?=$h($brand[$key])?>"><?=$h($brand[$key])?></a><?php elseif($key==='phone'&&preg_match('/^\+?[0-9 ()-]+$/D',$brand[$key])):?><a href="tel:<?=$h(preg_replace('/[^0-9+]/','',$brand[$key]))?>"><?=$h($brand[$key])?></a><?php else:?><?=$h($brand[$key])?><?php endif;?></p><?php endforeach;?></div></div></section><?php endif;?><?php endif;?></main><footer class="premium-footer"><div class="public-inner footer-grid"><div><strong><?=$h($brand['company_name'])?></strong><p>© <?=date('Y')?> · Tous droits réservés.</p></div><?php if($available):?><nav aria-label="Navigation de pied de page"><?php foreach($sections as $key=>$label):if(empty($data[$key]))continue;?><a href="#<?=$key?>"><?=$h($label)?></a><?php endforeach;?></nav><?php endif;?><a href="#accueil">Retour en haut ↑</a></div></footer></body></html>